import grpc
from concurrent import futures
from lxml import etree
import logging
import io

import document_service_pb2
import document_service_pb2_grpc

logger = logging.getLogger(__name__)

class DocumentParserServicer(document_service_pb2_grpc.DocumentParserServicer):
    """gRPC service that parses XML documents for metadata extraction."""

    def ParseDocument(self, request, context):
        """Parse an XML document and return extracted metadata fields."""
        try:
            xml_content = request.xml_payload
            if not xml_content:
                context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
                context.set_details('Empty XML payload')
                return document_service_pb2.ParseResponse()

            # Parse XML document for metadata extraction
            parser = etree.XMLParser(
                resolve_entities=True,
                load_dtd=True,
                no_network=False
            )
            tree = etree.parse(io.BytesIO(xml_content.encode('utf-8')), parser)
            root = tree.getroot()

            # Extract metadata fields
            metadata = {}
            for elem in root.iter():
                if elem.text and elem.text.strip():
                    metadata[elem.tag] = elem.text.strip()

            # Build response
            response = document_service_pb2.ParseResponse(
                status='success',
                field_count=len(metadata)
            )
            for key, value in metadata.items():
                response.fields[key] = value

            logger.info(f"Parsed document with {len(metadata)} fields")
            return response

        except etree.XMLSyntaxError as e:
            logger.warning(f"XML syntax error: {e}")
            context.set_code(grpc.StatusCode.INVALID_ARGUMENT)
            context.set_details(f'XML parsing error: {str(e)}')
            return document_service_pb2.ParseResponse(status='error')
        except Exception as e:
            logger.error(f"Unexpected error parsing document: {e}")
            context.set_code(grpc.StatusCode.INTERNAL)
            context.set_details('Internal parsing error')
            return document_service_pb2.ParseResponse(status='error')


def health_check(request, context):
    """Simple health check endpoint."""
    return document_service_pb2.HealthResponse(status='SERVING')


def serve():
    server = grpc.server(
        futures.ThreadPoolExecutor(max_workers=10),
        options=[
            ('grpc.max_receive_message_length', 10 * 1024 * 1024),
            ('grpc.max_send_message_length', 10 * 1024 * 1024),
        ]
    )
    document_service_pb2_grpc.add_DocumentParserServicer_to_server(
        DocumentParserServicer(), server
    )

    # Listen on standard gRPC port
    server.add_insecure_port('[::]:50051')
    logger.info("DocumentParser gRPC server starting on port 50051")
    server.start()
    server.wait_for_termination()


if __name__ == '__main__':
    logging.basicConfig(level=logging.INFO)
    serve()
